library(shiny)
library(readxl)
library(dplyr)
library(tibble)
library(DT)

calc_Chla <- function(df, K, A, blanks) {
  required <- c("Fb", "Fa", "Vol", "Level_Fb", "Level_Fa")
  missing_cols <- setdiff(required, names(df))
  if (length(missing_cols) > 0) {
    stop("Colonnes manquantes : ", paste(missing_cols, collapse = ", "))
  }

  blank_cols <- c("Level", "Fb.blank", "Fa.blank")
  missing_blanks <- setdiff(blank_cols, names(blanks))
  if (length(missing_blanks) > 0) {
    stop("Colonnes manquantes dans les blancs : ", paste(missing_blanks, collapse = ", "))
  }

  # Le facteur de dilution vaut 1 par défaut. Les volumes sont facultatifs.
  if ("FD" %in% names(df)) {
    fd <- df$FD
    fd[is.na(fd)] <- 1
  } else if (all(c("V_extrait", "V_acetone") %in% names(df))) {
    fd <- (df$V_extrait + df$V_acetone) / df$V_extrait
    fd[is.na(fd)] <- 1
  } else {
    fd <- rep(1, nrow(df))
  }
  df$FD <- fd

  level_fb <- toupper(trimws(as.character(df$Level_Fb)))
  level_fa <- toupper(trimws(as.character(df$Level_Fa)))
  blank_levels <- toupper(trimws(as.character(blanks$Level)))
  level_fb[level_fb == ""] <- NA_character_
  level_fa[level_fa == ""] <- NA_character_
  idx_fb <- match(level_fb, blank_levels)
  idx_fa <- match(level_fa, blank_levels)
  if (any(!is.na(level_fb) & is.na(idx_fb)) ||
      any(!is.na(level_fa) & is.na(idx_fa))) {
    stop("Certains niveaux (L/M/H) n'ont pas de blanc associé.")
  }

  Fb_c <- df$Fb - blanks$Fb.blank[idx_fb]
  Fa_c <- df$Fa - blanks$Fa.blank[idx_fa]

  df$Chla <- df$FD * K * (Fb_c - Fa_c) / df$Vol
  df$Phaeo <- df$FD * K * (A * Fa_c - Fb_c) / df$Vol
  df
}

ui <- fluidPage(
  tags$head(tags$script(HTML(
    "Shiny.addCustomMessageHandler('telecharger_csv', function(message) {
       var blob = new Blob([\"\\ufeff\", message.contenu], {type: 'text/csv;charset=utf-8;'});
       var lien = document.createElement('a');
       lien.href = URL.createObjectURL(blob);
       lien.download = message.nom;
       document.body.appendChild(lien);
       lien.click();
       document.body.removeChild(lien);
       URL.revokeObjectURL(lien.href);
     });"
  ))),
  titlePanel("Calcul de la chlorophylle a et des phéopigments"),
  sidebarLayout(
    sidebarPanel(
      h4("1. Données"),
      fileInput("file", "Charger un fichier (.csv ou .xlsx)",
                accept = c(".csv", ".xlsx")),
      helpText("Colonnes requises : Fb, Fa, Vol, Level_Fb et Level_Fa. FD est facultatif (1 par défaut si absent ou NA). Si FD est absent, les colonnes facultatives V_extrait et V_acetone permettent de le calculer : (V_extrait + V_acetone) / V_extrait (par exemple 2 mL + 6 mL donne FD = 4)."),

      h4("2. Facteurs de calibration"),
      numericInput("K", "K (inclut le volume d'extraction)", value = 1.789, step = 0.001),
      numericInput("A", "A (ratio acide)", value = 2.052, step = 0.001),

      h4("3. Valeurs de blanc"),
      helpText("Fluorescence des blancs pour chaque échelle."),
      fluidRow(
        column(4, strong("Échelle")),
        column(4, strong("Fb blanc")),
        column(4, strong("Fa blanc"))
      ),
      fluidRow(
        column(4, "L"),
        column(4, numericInput("fb_L", NULL, 0)),
        column(4, numericInput("fa_L", NULL, 0))
      ),
      fluidRow(
        column(4, "M"),
        column(4, numericInput("fb_M", NULL, 0)),
        column(4, numericInput("fa_M", NULL, 0))
      ),
      fluidRow(
        column(4, "H"),
        column(4, numericInput("fb_H", NULL, 0)),
        column(4, numericInput("fa_H", NULL, 0))
      ),

      hr(),
      actionButton("dl_btn", "Télécharger le résultat (.csv)")
    ),
    mainPanel(
      uiOutput("msg"),
      DTOutput("table")
    )
  )
)

server <- function(input, output, session) {
  data_in <- reactive({
    req(input$file)
    ext <- tolower(tools::file_ext(input$file$name))
    if (ext == "csv") {
      premiere_ligne <- readLines(input$file$datapath, n = 1, warn = FALSE)
      if (grepl(";", premiere_ligne)) {
        tryCatch(
          read.csv2(input$file$datapath, check.names = FALSE, blank.lines.skip = FALSE, fill = TRUE),
          error = function(e) read.csv(input$file$datapath, check.names = FALSE, blank.lines.skip = FALSE, fill = TRUE)
        )
      } else {
        tryCatch(
          read.csv(input$file$datapath, check.names = FALSE, blank.lines.skip = FALSE, fill = TRUE),
          error = function(e) read.csv2(input$file$datapath, check.names = FALSE, blank.lines.skip = FALSE, fill = TRUE)
        )
      }
    } else if (ext == "xlsx") {
      readxl::read_excel(input$file$datapath)
    } else {
      stop("Format de fichier non pris en charge. Utilisez .csv ou .xlsx.")
    }
  })

  blanks <- reactive({
    tibble(
      Level = c("L", "M", "H"),
      Fb.blank = c(input$fb_L, input$fb_M, input$fb_H),
      Fa.blank = c(input$fa_L, input$fa_M, input$fa_H)
    )
  })

  result <- reactive({
    req(data_in(), input$K, input$A)
    calc_Chla(data_in(), input$K, input$A, blanks())
  })

  output$msg <- renderUI({
    res <- tryCatch(result(), error = function(e) e)
    if (inherits(res, "error")) {
      div(style = "color:red;", strong("Erreur : "), conditionMessage(res))
    }
  })

  output$table <- renderDT({
    res <- tryCatch(result(), error = function(e) e)
    req(!inherits(res, "error"))
    datatable(res, options = list(pageLength = 20, scrollX = TRUE)) |>
      formatRound(c("FD", "Chla", "Phaeo"), 3)
  })

  observeEvent(input$dl_btn, {
    res <- tryCatch(result(), error = function(e) e)
    req(!inherits(res, "error"))
    fichier_temp <- tempfile(fileext = ".csv")
    on.exit(unlink(fichier_temp), add = TRUE)
    # Variante : séparateur ';' avec décimale '.' -> write.table(res, tmp, sep = ';', dec = '.', row.names = FALSE, fileEncoding = 'UTF-8')
    write.csv(res, fichier_temp, row.names = FALSE, fileEncoding = "UTF-8", na = "")
    contenu <- paste(readLines(fichier_temp, encoding = "UTF-8", warn = FALSE), collapse = "\n")
    session$sendCustomMessage(
      "telecharger_csv",
      list(nom = paste0("chla_resultats_", Sys.Date(), ".csv"), contenu = contenu)
    )
  })
}

shinyApp(ui, server)
